alter table public.company_roles add constraint company_roles_vc_salary_range_check CHECK (((source_provider IS DISTINCT FROM 'vc_portfolio'::text) OR (((salary_range IS NULL) AND (salary_min IS NULL) AND (salary_max IS NULL) AND (salary_currency IS NULL) AND (salary_period IS NULL)) OR ((salary_range IS NOT NULL) AND (salary_min IS NOT NULL) AND (salary_max IS NOT NULL) AND (salary_min <= salary_max) AND (NULLIF(TRIM(BOTH FROM salary_currency), ''::text) IS NOT NULL) AND (salary_currency = upper(TRIM(BOTH FROM salary_currency))) AND (salary_period = ANY (ARRAY['hour'::text, 'day'::text, 'week'::text, 'biweek'::text, 'month'::text, 'quarter'::text, 'year'::text, 'one_time'::text]))))));
