alter table public.talent_behavior_contexts add constraint talent_behavior_contexts_pkey PRIMARY KEY (talent_id);
alter table public.talent_contexts add constraint talent_contexts_collection_check CHECK ((collection = ANY (ARRAY['brief'::text, 'memory'::text])));
alter table public.talent_contexts add constraint talent_contexts_content_check CHECK (((length(btrim(content)) >= 1) AND (length(btrim(content)) <= 8000)));
alter table public.talent_contexts add constraint talent_contexts_importance_check CHECK ((((collection = 'brief'::text) AND (importance IS NULL)) OR ((collection = 'memory'::text) AND (importance IS NOT NULL) AND ((importance >= 1) AND (importance <= 3)))));
alter table public.talent_contexts add constraint talent_contexts_key_check CHECK (((key IS NULL) OR ((collection = 'brief'::text) AND ((length(btrim(key)) >= 1) AND (length(btrim(key)) <= 160)))));
alter table public.talent_contexts add constraint talent_contexts_label_check CHECK ((((collection = 'brief'::text) AND (label IS NOT NULL) AND ((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 160))) OR ((collection = 'memory'::text) AND (label IS NULL))));
alter table public.talent_contexts add constraint talent_contexts_pkey PRIMARY KEY (id);
